const hex6 = (M, argb) => M.hexFromArgb(argb).slice(1);

test('导出 API 形状与 VARIANTS 清单', () => {
  const M = load();
  assert.deepStrictEqual(Array.from(M.VARIANTS), [
    'tonalSpot', 'fidelity', 'monochrome', 'neutral', 'vibrant', 'expressive', 'content', 'rainbow', 'fruitSalad',
  ]);
  for (const fn of ['argbFromRgb', 'rgbFromArgb', 'hexFromArgb', 'argbFromHex', 'schemeFromSeed']) {
    assert.strictEqual(typeof M[fn], 'function', fn);
  }
  assert.strictEqual(typeof M.Hct.fromInt, 'function');
  assert.strictEqual(typeof M.Hct.from, 'function');
  assert.strictEqual(typeof M.TonalPalette.fromHueAndChroma, 'function');
  const scheme = M.schemeFromSeed(0xff6750a4, false, 'tonalSpot');
  assert.deepStrictEqual(Object.keys(scheme).sort(), ROLES.slice().sort());
  for (const k of ROLES) {
    assert.ok(Number.isInteger(scheme[k]) && scheme[k] >= 0xff000000 && scheme[k] <= 0xffffffff, k);
  }
});

test('颜色工具：argbFromRgb / rgbFromArgb / hexFromArgb / argbFromHex', () => {
  const M = load();
  assert.strictEqual(M.argbFromRgb(0x67, 0x50, 0xa4), 0xff6750a4);
  assert.deepStrictEqual({ ...M.rgbFromArgb(0xff6750a4) }, { r: 0x67, g: 0x50, b: 0xa4 });
  assert.strictEqual(M.hexFromArgb(0xff0b57d0), '#0b57d0');
  assert.strictEqual(M.hexFromArgb(0xff000000), '#000000');
  assert.strictEqual(M.argbFromHex('#6750A4'), 0xff6750a4);
  assert.strictEqual(M.argbFromHex('6750a4'), 0xff6750a4);
  assert.strictEqual(M.argbFromHex('#fff'), 0xffffffff);
  assert.strictEqual(M.argbFromHex('#806750a4'), 0xff6750a4);
  assert.strictEqual(M.argbFromHex('#12345'), null);
  assert.strictEqual(M.argbFromHex('#zzzzzz'), null);
  assert.strictEqual(M.argbFromHex(null), null);
});

test('schemeFromSeed 与 Dart material_color_utilities 0.13.0 逐角色精确一致', () => {
  const M = load();
  const mismatches = [];
  for (const [variant, seed, dark, contrast, packed] of SCHEMES) {
    const scheme = M.schemeFromSeed(parseInt(seed, 16) | 0xff000000, dark === 1, variant, contrast);
    ROLES.forEach((role, i) => {
      const want = packed.substr(i * 6, 6);
      const got = hex6(M, scheme[role]);
      if (got !== want) mismatches.push(variant + ' #' + seed + (dark ? ' dark' : ' light') + ' c=' + contrast + ' ' + role + ': ' + got + ' != ' + want);
    });
  }
  assert.strictEqual(SCHEMES.length >= 200, true);
  assert.deepStrictEqual(mismatches, []);
});

test('Hct.from(h, c, t).toInt() 精确一致（含极暗 / 极亮 / 超色域）', () => {
  const M = load();
  const mismatches = [];
  for (const [h, c, t, want] of HCT) {
    const got = hex6(M, M.Hct.from(h, c, t).toInt());
    if (got !== want) mismatches.push(h + '/' + c + '/' + t + ': ' + got + ' != ' + want);
  }
  assert.deepStrictEqual(mismatches, []);
});

test('TonalPalette.fromHueAndChroma(h, c).tone(t) 精确一致', () => {
  const M = load();
  for (const [h, c, , , , packed] of PALETTES) {
    const palette = M.TonalPalette.fromHueAndChroma(h, c);
    assert.strictEqual(palette.hue, h);
    assert.strictEqual(palette.chroma, c);
    PALETTE_TONES.forEach((t, i) => {
      assert.strictEqual(hex6(M, palette.tone(t)), packed.substr(i * 6, 6), h + '/' + c + ' T' + t);
    });
  }
});

test('Hct.fromInt 的 hue / chroma / tone 与 Dart 一致（tone 精确，hue/chroma 容 1 ULP 级 libm 差）', () => {
  const M = load();
  for (const [seed, hue, chroma, tone] of FROM_INT) {
    const argb = parseInt(seed, 16) | 0xff000000;
    const hct = M.Hct.fromInt(argb);
    assert.ok(Math.abs(hct.hue - hue) < 1e-9, seed + ' hue');
    assert.ok(Math.abs(hct.chroma - chroma) < 1e-9, seed + ' chroma');
    assert.ok(Math.abs(hct.tone - tone) < 1e-9, seed + ' tone');
    assert.strictEqual(hct.toInt(), argb >>> 0);
  }
});

test('未知 variant 回落 tonalSpot、contrastLevel 缺省为 0', () => {
  const M = load();
  const base = M.schemeFromSeed(0xff0b57d0, true, 'tonalSpot', 0);
  assert.deepStrictEqual({ ...M.schemeFromSeed(0xff0b57d0, true, 'nope') }, { ...base });
  assert.deepStrictEqual({ ...M.schemeFromSeed(0xff0b57d0, true, 'tonalSpot') }, { ...base });
});

test('脚本可在没有 window / self 的 service worker 式全局里加载', () => {
  const ctx = vm.createContext({});
  vm.runInContext(SRC, ctx);
  assert.strictEqual(typeof vm.runInContext('globalThis.fushiMaterialColor.schemeFromSeed', ctx), 'function');
});
